"""
    Gets a string representing the number of seconds in hours, minutes, and seconds,
    but will not print leading zeroes.
    """
def time_string(seconds: Any) -> object {
    (minutes, seconds) = divmod(seconds, 60);
    (hours, minutes) = divmod(minutes, 60);
    hour_string = ("%dh " % hours) if (hours > 0) else "";
    minute_string = ("%dm " % minutes) if (minutes > 0) else "";
    second_string = ("%ds" % seconds) if (seconds > 0) else "";
    return ("%s%s%s" % (hour_string, minute_string, second_string));
}

"""Return offset from prototype position.
    Positional arguments:
    num -- the number of the object, starting from 0
    columns -- how many columns before wrapping
    spacing -- a tuple of (x,y), spacing between objects
    """
def get_offset(num: Any, columns: Any, spacing: Any) -> object {
    x_offset = (num % columns) * spacing[0];
    y_offset = (num // columns) * spacing[1];
    return (x_offset, y_offset);
}

"""
    Format the name of config parameter, adding the target language of necessary.

    :param config_parameter: Name of config parameter.
    :type config_parameter: str
    :param language: Pipeline language.
    :type language: str
    :return: Formatted config parameter.
    :rtype: str
    """
def format_config_parameter(config_parameter: Any, language: Any) -> object {
    if ("{language}" in config_parameter) {
        return config_parameter.format(language=language.upper());
    }
    return config_parameter;
}

