    if isinstance(color, int) {
        escape = "\x1b[{0}8:5:{1}m".format(mode, color);
    } elif isinstance(color, `tuple) {
        (r, g, b) = color;
        escape = "\x1b[{0}8;2;{1};{2};{3}m".format(mode, r, g, b);
    } elif isinstance(color, str) {
        if not color.startswith('#') {
